// Glue for "Read the PDF from the row" in 02 Process. The documents row holds the PDF; it becomes the binary that
// "Pull the text out of the PDF" reads. Nothing is downloaded.
const cfg = $('Config').first().json;
if (typeof cfg.pdf_base64 !== 'string' || !cfg.pdf_base64.startsWith('JVBERi0')) throw new Error(`no PDF in the row for ${cfg.document_id}`);
const data = await this.helpers.prepareBinaryData(Buffer.from(cfg.pdf_base64, 'base64'), cfg.filename, 'application/pdf');
return [{ json: { document_id: cfg.document_id }, binary: { data } }];

const VISION_REQUEST_TEMPLATE = {"model": "", "temperature": 0, "max_tokens": 400, "response_format": {"type": "json_schema", "json_schema": {"name": "office_document", "strict": true, "schema": {"type": "object", "properties": {"doc_type": {"type": "string", "enum": ["cost", "deal", "credit"]}, "doc_key": {"type": "string", "description": "Belegnummer, for example PO-1042"}, "version": {"type": "integer"}, "cost_center": {"type": "string", "description": "Kostenstelle, for example CC-BER-01"}, "date": {"type": "string", "description": "YYYY-MM-DD, converted from the German DD.MM.YYYY"}, "counterparty": {"type": "string"}, "category": {"type": "string", "enum": ["people", "cloud", "gpu", "office", "travel", "none"]}, "amount": {"type": "number", "description": "EUR as a plain number, converted from German format"}, "description_en": {"type": "string", "description": "the Beschreibung as one English sentence"}}, "required": ["doc_type", "doc_key", "version", "cost_center", "date", "counterparty", "category", "amount", "description_en"], "additionalProperties": false}}}, "plugins": [{"id": "file-parser", "pdf": {"engine": ""}}], "messages": [{"role": "system", "content": "You read one German business document of Q8nten GmbH, an event agency: a Bestellung (an order to a supplier), a Kundenauftrag (a sponsor or exhibitor order), or a Gutschrift (a supplier credit note). Return JSON only with these keys: doc_type (cost for Bestellung, deal for Kundenauftrag, credit for Gutschrift), doc_key (the Belegnummer, for example PO-1042), version (the integer after Version), cost_center (the Kostenstelle, for example CC-BER-01), date (Datum, written DD.MM.YYYY in the document, returned as YYYY-MM-DD), counterparty (the Lieferant or Kunde), category (people for Personal und Crew, cloud for Marketing und Werbung, gpu for Bühne und Technik, office for Veranstaltungsort, travel for Catering, none for a Kundenauftrag), amount (Betrag or Auftragswert as a number: German format uses dots for thousands and a comma for decimals, so 12.300,00 € is 12300), description_en (the Beschreibung translated to one English sentence)."}, {"role": "user", "content": [{"type": "text", "text": "Extract the fields."}, {"type": "file", "file": {"filename": "document.pdf", "file_data": "data:application/pdf;base64,"}}]}]};
// Glue for "Prepare the vision request" in 02 Process. build_workflows.py injects VISION_REQUEST_TEMPLATE above it:
// scripts/openrouter_check.py's extraction_body with an empty PDF, so n8n sends the request the live gate tested.
// The PDF comes from the row; the binary passes through for "Pull the text out of the PDF".
const cfg = $('Config').first().json;
const body = JSON.parse(JSON.stringify(VISION_REQUEST_TEMPLATE));
body.model = cfg.OPENROUTER_MODEL;
body.plugins[0].pdf.engine = cfg.PDF_ENGINE;
body.messages[1].content.find((part) => part.type === 'file').file.file_data += cfg.pdf_base64;
return [{ json: { body }, binary: $input.first().binary }];

// Stage 1: a regex read of the extracted PDF text. Pasted into n8n Code nodes without the module.exports line.
// ponytail: deliberately naive about money. Commas are dropped, so the German "12.300,00 €" reads as 12.3;
// the vision stage corrects it. Every other field is read properly.

const COARSE_LABELS = ['Belegnummer', 'Version', 'Datum', 'Kostenstelle', 'Standort', 'Lieferant', 'Kunde', 'Kategorie',
  'Beschreibung', 'Betrag', 'Auftragswert', 'Eingereicht von', 'Synthetischer Beleg'];
// A value ends at the end of its line or where the next label starts, so flattened text reads the same.
const COARSE_UNTIL = `(?=\\s+(?:${COARSE_LABELS.join('|')})\\b|\\n|$)`;
const COARSE_TYPES = { BESTELLUNG: 'cost', KUNDENAUFTRAG: 'deal', GUTSCHRIFT: 'credit' };
const COARSE_CATEGORIES = {
  'Personal und Crew': 'people', 'Marketing und Werbung': 'cloud', 'Bühne und Technik': 'gpu',
  'Veranstaltungsort': 'office', 'Catering': 'travel',
};

function coarseRead(text) {
  const t = text || '';
  const grab = (re) => {
    const m = t.match(re);
    return m ? m[1].trim() : null;
  };
  const title = grab(/\b(BESTELLUNG|KUNDENAUFTRAG|GUTSCHRIFT)\b/);
  const version = grab(/Version:\s*(\d+)/);
  const date = t.match(/Datum:\s*(\d{2})\.(\d{2})\.(\d{4})/);
  const category = grab(new RegExp(`Kategorie:\\s*(.+?)${COARSE_UNTIL}`));
  const rawAmount = grab(/(?:Betrag|Auftragswert):\s*([0-9][0-9.,]*)/);
  return {
    doc_type: title ? COARSE_TYPES[title] : null,
    doc_key: grab(/Belegnummer:\s*((?:PO|DEAL|CN)-\d{4})/),
    version: version === null ? null : Number(version),
    date: date ? `${date[3]}-${date[2]}-${date[1]}` : null,
    cost_center: grab(/Kostenstelle:\s*(CC-[A-Z]{3}-\d{2})/),
    counterparty: grab(new RegExp(`(?:Lieferant|Kunde):\\s*(.+?)${COARSE_UNTIL}`)),
    category: category !== null && Object.hasOwn(COARSE_CATEGORIES, category) ? COARSE_CATEGORIES[category] : null,
    amount: rawAmount === null ? null : parseFloat(rawAmount.replace(/,/g, '')),
  };
}

// Glue for "Coarse read with regex" in 02 Process; coarse.js is pasted above it. Empty text (a scanned PDF) is valid.
const text = $json.text || '';
return [{ json: { regex_fields: JSON.stringify(coarseRead(text)), text } }];

const OFFICES = [{"office_id": "berlin", "code": "ber", "name": "DevSummit Berlin", "region": "DACH", "manager_id": "m_anna", "manager_name": "Anna", "worker_id": "w_tom", "worker_name": "Tom", "cost_center": "CC-BER-01", "budgets": {"people": 160000, "cloud": 90000, "gpu": 120000, "office": 220000, "travel": 180000}}, {"office_id": "munich", "code": "muc", "name": "CloudTage München", "region": "DACH", "manager_id": "m_anna", "manager_name": "Anna", "worker_id": "w_tom", "worker_name": "Tom", "cost_center": "CC-MUC-01", "budgets": {"people": 120000, "cloud": 70000, "gpu": 150000, "office": 160000, "travel": 140000}}, {"office_id": "vienna", "code": "vie", "name": "AI Forum Wien", "region": "DACH", "manager_id": "m_anna", "manager_name": "Anna", "worker_id": "w_lena", "worker_name": "Lena", "cost_center": "CC-VIE-01", "budgets": {"people": 90000, "cloud": 50000, "gpu": 80000, "office": 120000, "travel": 100000}}, {"office_id": "amsterdam", "code": "ams", "name": "DataWeek Amsterdam", "region": "International", "manager_id": "m_ben", "manager_name": "Ben", "worker_id": "w_jules", "worker_name": "Jules", "cost_center": "CC-AMS-01", "budgets": {"people": 110000, "cloud": 80000, "gpu": 100000, "office": 150000, "travel": 130000}}, {"office_id": "paris", "code": "par", "name": "Paris Tech Days", "region": "International", "manager_id": "m_ben", "manager_name": "Ben", "worker_id": "w_jules", "worker_name": "Jules", "cost_center": "CC-PAR-01", "budgets": {"people": 130000, "cloud": 100000, "gpu": 140000, "office": 200000, "travel": 160000}}, {"office_id": "london", "code": "lon", "name": "FinTech Expo London", "region": "International", "manager_id": "m_ben", "manager_name": "Ben", "worker_id": "w_mia", "worker_name": "Mia", "cost_center": "CC-LON-01", "budgets": {"people": 170000, "cloud": 140000, "gpu": 160000, "office": 260000, "travel": 210000}}];
// Stage 2: validate what the vision model read. Pasted into n8n Code nodes without the module.exports line.

const DOCUMENT_TYPES = { cost: 'PO', deal: 'DEAL', credit: 'CN' };
const DOCUMENT_CATEGORIES = ['people', 'cloud', 'gpu', 'office', 'travel'];

// Formatted amounts: the later of "," and "." is the decimal point; a lone separator followed by exactly
// three digits is a thousands separator (EUR never has three decimals); repeated separators are thousands.
function toNumber(value) {
  if (typeof value === 'number') return value;
  const s = String(value ?? '').replace(/[^\d.,-]/g, '');
  if (!/\d/.test(s)) return NaN;
  const commas = (s.match(/,/g) || []).length;
  const dots = (s.match(/\./g) || []).length;
  if (commas && dots) {
    return Number(s.lastIndexOf(',') > s.lastIndexOf('.') ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, ''));
  }
  if (!commas && !dots) return Number(s);
  const separator = commas ? ',' : '.';
  const digitsAfter = s.length - s.lastIndexOf(separator) - 1;
  const isThousands = commas + dots > 1 || digitsAfter === 3;
  return Number(isThousands ? s.split(separator).join('') : s.replace(separator, '.'));
}

function isCalendarDate(iso) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return false;
  const [y, m, d] = iso.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
}

function validateDocument(obj, expectedCostCenter) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) throw new Error('expected a JSON object');
  const docType = obj.doc_type;
  if (!Object.hasOwn(DOCUMENT_TYPES, docType)) throw new Error(`bad doc_type ${docType}`);
  const docKey = String(obj.doc_key ?? '').trim();
  if (!/^(PO|DEAL|CN)-\d{4}$/.test(docKey) || !docKey.startsWith(DOCUMENT_TYPES[docType] + '-')) {
    throw new Error(`bad doc_key ${obj.doc_key} for ${docType}`);
  }
  const version = Number(obj.version);
  if (!Number.isInteger(version) || version < 1) throw new Error(`bad version ${obj.version}`);
  const date = String(obj.date ?? '');
  if (!isCalendarDate(date)) throw new Error(`bad date ${obj.date}`);
  const rawCategory = obj.category === null || obj.category === undefined ? 'none' : String(obj.category);
  const category = docType === 'deal'
    ? (rawCategory === 'none' || rawCategory === '' ? null : undefined)
    : (DOCUMENT_CATEGORIES.includes(rawCategory) ? rawCategory : undefined);
  if (category === undefined) throw new Error(`bad category ${obj.category} for ${docType}`);
  const amount = toNumber(obj.amount);
  if (!Number.isFinite(amount)) throw new Error(`amount not numeric: ${obj.amount}`);
  if (amount <= 0) throw new Error(`amount must be positive: ${obj.amount}`);
  const counterparty = String(obj.counterparty ?? '').trim();
  if (!counterparty) throw new Error('missing counterparty');
  const description = String(obj.description_en ?? '').trim();
  if (!description) throw new Error('missing description_en');
  const costCenter = String(obj.cost_center ?? '').trim().toUpperCase();
  if (costCenter !== String(expectedCostCenter).toUpperCase()) {
    throw new Error(`cost center mismatch: read ${obj.cost_center}, expected ${expectedCostCenter}`);
  }
  return {
    doc_type: docType, doc_key: docKey, version, cost_center: costCenter, date, counterparty, category, amount,
    description_en: description.slice(0, 160),
  };
}

// Glue for "Validate the fields" in 02 Process; validate.js and OFFICES are pasted above it. A throw goes to the
// error output. The document must carry its own office's cost center.
const office = OFFICES.find((o) => o.office_id === $('Config').first().json.office_id);
if (!office) throw new Error(`unknown office ${$('Config').first().json.office_id}`);
let reply;
try {
  reply = JSON.parse($json.choices[0].message.content);
} catch {
  throw new Error('vision reply is not bare JSON');
}
return [{ json: { llm_fields: JSON.stringify(validateDocument(reply, office.cost_center)) } }];
